create function pg_temp.assert_true(value boolean,label text) returns text language plpgsql as $$ begin
 if value is distinct from true then raise exception 'FAIL: %',label; end if; return label; end; $$;
create function pg_temp.expect_error(statement text,expected_state text,label text) returns text language plpgsql as $$ begin
 begin execute statement; exception when others then if sqlstate=expected_state then return label; end if;
 raise exception 'FAIL: %, expected %, got % (%)',label,expected_state,sqlstate,sqlerrm; end;
 raise exception 'FAIL: %, statement unexpectedly succeeded',label; end; $$;
insert into auth.users(id) values('40000000-0000-0000-0000-000000000001'),('40000000-0000-0000-0000-000000000002'),('40000000-0000-0000-0000-000000000003');
set local role service_role;
select public.auth_signup('40000000-0000-0000-0000-000000000001','a@internal.invalid','account_a','별명 A','Membership A',null,repeat('a',64),repeat('b',64));
select public.auth_signup('40000000-0000-0000-0000-000000000002','b@internal.invalid','account_b','별명 B','Membership B',null,repeat('c',64),repeat('d',64));
select public.auth_signup('40000000-0000-0000-0000-000000000003','c@internal.invalid','account_c','구성원',null,repeat('b',64),repeat('e',64),null);
select public.auth_add_membership('40000000-0000-0000-0000-000000000001','다른 별명',null,repeat('d',64),null);
select pg_temp.assert_true((select count(*)=2 from public.band_memberships where user_id='40000000-0000-0000-0000-000000000001'),'one account belongs to multiple bands') as assertion;
select pg_temp.assert_true((select count(distinct band_role)=2 from public.band_memberships where user_id='40000000-0000-0000-0000-000000000001'),'one account can be leader and member in different bands') as assertion;
select pg_temp.assert_true((select count(distinct nickname)=2 from public.band_memberships where user_id='40000000-0000-0000-0000-000000000001'),'one account has independent band nicknames') as assertion;
select pg_temp.assert_true((select count(*)=1 from public.auth_account_lookup(' ACCOUNT_A ')),'account lookup is case-insensitive') as assertion;
select pg_temp.expect_error($s$select public.auth_add_membership('40000000-0000-0000-0000-000000000002',' 별명 a ',null,repeat('b',64),null)$s$,'23505','nickname unique within same band') as assertion;
select pg_temp.expect_error($s$select public.auth_add_membership('40000000-0000-0000-0000-000000000001','다른 닉',null,repeat('d',64),null)$s$,'23505','same account cannot join same band twice or change role by invite') as assertion;
select pg_temp.expect_error($s$select public.auth_signup(gen_random_uuid(),'x@internal.invalid',' ACCOUNT_A ','닉','Band',null,repeat('1',64),repeat('2',64))$s$,'P0001','invalid signup ID whitespace rejected at server') as assertion;
select pg_temp.expect_error($s$select public.auth_invite_rotate('40000000-0000-0000-0000-000000000001',(select band_id from public.band_memberships where user_id='40000000-0000-0000-0000-000000000002'),repeat('f',64))$s$,'42501','leadership in band A cannot rotate invite in member band B') as assertion;
select pg_temp.assert_true((select recovery_hash=repeat('e',64) from private.account_mapping where auth_user_id='40000000-0000-0000-0000-000000000003'),'new member receives account recovery key independently of role') as assertion;
select public.auth_update_login_id('40000000-0000-0000-0000-000000000001','renamed_id');
select pg_temp.assert_true((select count(*)=1 from public.auth_account_lookup('renamed_id')),'login ID change updates account lookup') as assertion;
select pg_temp.assert_true((select count(*)=0 from public.auth_account_lookup('account_a')),'old login ID no longer authenticates after explicit change') as assertion;
select pg_temp.assert_true((select internal_login_email='a@internal.invalid' and login_id_normalized='renamed_id' from private.account_mapping where auth_user_id='40000000-0000-0000-0000-000000000001'),'ID change retains internal email/PIN binding and cascades private mapping') as assertion;
select pg_temp.expect_error($s$select public.auth_update_login_id('40000000-0000-0000-0000-000000000001','ACCOUNT_B')$s$,'23505','login ID unique globally across bands') as assertion;
select pg_temp.expect_error($s$select public.auth_update_login_id('40000000-0000-0000-0000-000000000001','bad id')$s$,'22023','login ID syntax enforced by DB') as assertion;
reset role;
insert into public.songs(id,title,artist,vocal_type,band_id) select 'members-a','곡 A','Artist','female',band_id from public.band_memberships where user_id='40000000-0000-0000-0000-000000000001' and band_role='leader';
insert into public.songs(id,title,artist,vocal_type,band_id) select 'members-b','곡 B','Artist','male',band_id from public.band_memberships where user_id='40000000-0000-0000-0000-000000000002';
set local role anon;
select pg_temp.expect_error('select * from public.band_memberships','42501','anonymous memberships denied') as assertion;
select pg_temp.expect_error('select public.cancel_member_pin_reset()','42501','anonymous reset approval mutation denied') as assertion;
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','40000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"40000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('request.headers','{}',true);
select pg_temp.assert_true(private.current_band_id() is null,'ambiguous multiband request without header fails closed') as assertion;
select pg_temp.assert_true((select count(*)=0 from public.songs),'missing band header exposes no songs for multiband account') as assertion;
select pg_temp.expect_error('select public.list_song_catalog()','42501','catalog requires unambiguous authorized band') as assertion;
select pg_temp.assert_true((select count(*)=2 from public.band_memberships),'account can list its own memberships without selected band') as assertion;
select pg_temp.assert_true((select count(*)=2 from public.bands),'account can read names of all joined bands') as assertion;
select pg_temp.assert_true((select count(*)=1 from public.profiles),'profile SELECT reveals only own login identity') as assertion;
select set_config('request.headers',jsonb_build_object('x-band-id',(select band_id::text from public.band_memberships where user_id=auth.uid() and band_role='leader'))::text,true);
select pg_temp.assert_true((select count(*)=1 and min(id)='members-a' from public.songs),'header selects only band A data') as assertion;
select pg_temp.assert_true((public.list_song_catalog()->>'total')::int=1,'catalog is scoped to selected band A') as assertion;
select pg_temp.assert_true((select count(*)=3 from public.band_memberships),'selected band includes other members plus own other memberships') as assertion;
select public.set_band_nickname(private.current_band_id(),'変更 닉네임');
select pg_temp.assert_true((select nickname='変更 닉네임' from public.band_memberships where user_id=auth.uid() and band_role='leader'),'member can change own band nickname') as assertion;
select pg_temp.assert_true((select nickname='다른 별명' from public.band_memberships where user_id=auth.uid() and band_role='member'),'nickname change leaves other band nickname untouched') as assertion;
select pg_temp.assert_true((select login_id='renamed_id' from public.profiles),'nickname change leaves login ID untouched') as assertion;
select pg_temp.expect_error($s$update public.band_memberships set band_role='leader'$s$,'42501','client cannot promote membership roles') as assertion;
select pg_temp.expect_error($s$update public.profiles set login_id='hijacked'$s$,'42501','client cannot bypass PIN reauthentication for ID change') as assertion;
select pg_temp.expect_error($s$select public.auth_account_lookup('account_b')$s$,'42501','account mapping remains server-only') as assertion;
select pg_temp.expect_error($s$select public.toggle_vote('members-b',1::smallint)$s$,'23503','member cannot vote in nonselected band even if also a member there') as assertion;
select set_config('request.headers',jsonb_build_object('x-band-id',(select band_id::text from public.band_memberships where user_id=auth.uid() and band_role='member'))::text,true);
select pg_temp.assert_true((select count(*)=1 and min(id)='members-b' from public.songs),'same account can switch to band B independently') as assertion;
insert into public.songs(title,artist,vocal_type) values('새 B곡','Artist','mixed');
select pg_temp.assert_true((select band_id=private.current_band_id() from public.songs where title='새 B곡'),'insert band default captures request header') as assertion;
select pg_temp.assert_true(public.toggle_vote('members-b',1::smallint)=1,'vote uses same global account ID in selected band') as assertion;
select public.add_comment('members-b','다중 밴드 익명 댓글');
select pg_temp.assert_true((select content='다중 밴드 익명 댓글' from public.get_comments('members-b')),'anonymous comments work with selected multiband identity') as assertion;
select pg_temp.assert_true((select not(to_jsonb(c)?'user_id') from public.get_comments('members-b') c),'comments still hide account identity after migration') as assertion;
with changed as(update public.songs set title='다른 밴드 덮어쓰기' where id='members-a' returning id)
 select pg_temp.assert_true((select count(*)=0 from changed),'selected band header prevents writes to another joined band') as assertion;
select public.save_rehearsal('2028-01-01',jsonb_build_array(jsonb_build_object('song_id','members-b','sessions',jsonb_build_array(jsonb_build_object('session_type','vocal','member_id',auth.uid(),'nickname_snapshot','wrong alias')))));
select pg_temp.assert_true((select nickname_snapshot='다른 별명' from public.rehearsal_sessions),'session assignments capture selected band nickname rather than global login ID') as assertion;
select pg_temp.assert_true((select likes=1 and comment_count=1 from public.get_song_stats(array['members-b'])),'song stats preserve per-account votes and comments under selected band') as assertion;
select pg_temp.expect_error('select * from private.pin_reset_requests','42501','reset approvals hidden from direct client reads') as assertion;
select public.request_member_pin_reset(private.current_band_id());
select pg_temp.expect_error('select public.get_member_reset_requests(private.current_band_id())','42501','member cannot read leader reset approval list') as assertion;
select set_config('request.headers','{"x-band-id":"00000000-0000-0000-0000-000000000099"}',true);
select pg_temp.assert_true(private.current_band_id() is null,'forged unjoined band header rejected') as assertion;
select set_config('request.headers','{"x-band-id":"not-a-uuid"}',true);
select pg_temp.assert_true(private.current_band_id() is null,'malformed band header fails closed without SQL exception') as assertion;
reset role;
set local role service_role;
select pg_temp.expect_error($s$select public.auth_claim_member_reset('40000000-0000-0000-0000-000000000001',(select band_id from public.band_memberships where user_id='40000000-0000-0000-0000-000000000001' and band_role='leader'),'40000000-0000-0000-0000-000000000003')$s$,'42501','leader cannot reset an account without its explicit approval') as assertion;
select pg_temp.assert_true((select count(*)=1 from public.auth_claim_member_reset('40000000-0000-0000-0000-000000000002',(select band_id from public.band_memberships where user_id='40000000-0000-0000-0000-000000000002'),'40000000-0000-0000-0000-000000000001')),'approved band B leader can claim account-wide reset once') as assertion;
select pg_temp.expect_error($s$select public.auth_claim_member_reset('40000000-0000-0000-0000-000000000002',(select band_id from public.band_memberships where user_id='40000000-0000-0000-0000-000000000002'),'40000000-0000-0000-0000-000000000001')$s$,'42501','consumed reset approval cannot be replayed') as assertion;
select pg_temp.assert_true(public.auth_swap_recovery('40000000-0000-0000-0000-000000000003',repeat('e',64),repeat('f',64)),'member account can use its own recovery key') as assertion;
select pg_temp.assert_true(not public.auth_swap_recovery('40000000-0000-0000-0000-000000000003',repeat('e',64),repeat('1',64)),'old member recovery key cannot be reused') as assertion;
reset role;
select pg_temp.assert_true(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'auth_%' and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE'))),'all account service RPCs deny direct browser execution') as assertion;
